  protected readonly form = new FormGroup({ personId: this.personId });
  protected readonly saving = signal(false);
  protected readonly error = signal('');

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
  }

  /** The lead's name with their grade in force on the sheet's today; blank when there is no lead. */
  protected readonly leadName = computed(() => {
    const id = this.crew().leadId;
    const lead = id === null ? undefined : this.people().find((p) => p.id === id);
    return lead === undefined ? '' : nameWithGrade(lead, this.session.sheet()?.today);
  });

  protected nameOf(id: number | null): string {
    return id === null ? '' : this.namesById().get(id) ?? '';
  }

  protected async submit(): Promise<void> {
    if (this.saving()) return;
    public void addMember(long personId) {
        members.add(new CrewMember(personId));
    }

    /** Give a person's place in the crew, as lead or member, to another person; a member place is dropped when
     *  that person is already in the crew, and on taking the lead they leave the members. */
    public void movePerson(long fromPersonId, long intoPersonId) {
        if (isLead(fromPersonId)) {
            leadId = intoPersonId;
            members.removeIf((m) -> m.getPersonId() == intoPersonId);
        }
        for (CrewMember m : List.copyOf(members)) {
            if (m.getPersonId() != fromPersonId) continue;
            if (includes(intoPersonId)) members.remove(m);
            else m.setPersonId(intoPersonId);
        }
    }

    /** Take the person out of the crew's members; nothing when they are not one. */
    public void removeMember(long personId) {
        members.removeIf((m) -> m.getPersonId() == personId);
    }

    /** Take the person out of the crew: as lead, leaving it with none, or as a member. */
    public void removePerson(long personId) {
        if (isLead(personId)) leadId = null;
        removeMember(personId);
    }
}
    }

    /**
     * Merge a person into another: the merged person's claims move to the other (numbers and dates kept),
     * listed after the other's claims in the order they were added, each keeping any figure a statement bound
     * it to; the merged person's statements count among the other's, whose last statement stays their own
     * (or, having none, becomes the merged person's); the merged name and aliases become aliases of the other; the merged person's patrons are added
     * to the other's (never the other themselves, nor twice), anyone naming the merged person as patron names
     * the other instead (not twice), and the merged person's pool memberships move to the other (their shares
     * added when the other is already a member), as do their places in crews (as lead or member; a member place
     * is dropped when the other is already in the crew). Their holds, watchers and contact are dropped,
     * and they leave the sheet. Refused unless the user is a steward of the sheet, for a merge into the
     * person themselves, and when either of them is retired. The person merged into.
     */
    @Transactional
    public Person merge(String sheetId, String user, long id, long intoId) {
        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can merge people.");
        }
        if (id == intoId) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be merged into themselves.");
